// Agoda — jump game family: can you reach the end (LeetCode 55), fewest jumps (45), and the reported
// "prime-3" scoring variant (reconstructed): from i you may move 1 forward or p forward, p a prime ending in 3.
public static class JumpGame {
    public static bool CanReach(int[] nums) {
        if (nums == null || nums.Length == 0) return false;
        long reach = 0;
        for (int i = 0; i < nums.Length; i++) {
            if (i > reach) return false;
            reach = Math.Max(reach, (long)i + nums[i]);
        }
        return true;
    }

    // Fewest jumps to the last index (BFS by layers, O(n)); -1 if unreachable.
    public static int MinJumps(int[] nums) {
        if (nums == null || nums.Length == 0) return -1;
        int jumps = 0; long end = 0, far = 0;
        for (int i = 0; i < nums.Length - 1; i++) {
            if (i > far) return -1;
            far = Math.Max(far, (long)i + nums[i]);
            if (i == end) { if (far <= i) return -1; jumps++; end = far; }
        }
        return jumps;
    }

    // Start on cell 0, finish exactly on cell n-1; each move is 1 step or p steps with p prime and p % 10 == 3.
    // Score = sum of the cells you land on (both ends included). Return the maximum score.
    public static long MaxScore(int[] cells) {
        if (cells == null || cells.Length == 0) throw new ArgumentException("no cells");
        int n = cells.Length;
        var steps = new List<int> { 1 };
        var composite = new bool[n + 1];
        for (int p = 2; p <= n; p++) {
            if (composite[p]) continue;
            if (p % 10 == 3) steps.Add(p);
            for (long q = (long)p * p; q <= n; q += p) composite[q] = true;
        }
        var best = new long[n];
        best[0] = cells[0];
        for (int i = 1; i < n; i++) {
            long b = long.MinValue;
            foreach (var s in steps) { if (s > i) break; b = Math.Max(b, best[i - s]); }
            best[i] = b + cells[i];
        }
        return best[n - 1];
    }
}
